-- TomoModForever 1.2.8 release notes.

TomoMod_RegisterLocale("enUS", {
    ["wn_128_alts"] = "Fixed - Mail, Alts tab, for real this time: on Forever a character has a first name and a surname, and only the pair is unique. Characters were saved by first name alone, so alts sharing a first name erased each other and the list stayed empty; mail also went to the first name only. Characters are now saved by full name (and GUID), letters go to the full name, and only alts of your ruleset and faction are listed. Log in once on each character to fill the list again. /tml alts shows what is saved.",
    ["wn_128_names"] = "Fixed - Mail: a typed \"Name-Surname\" is now read as one full name, not as a name and a realm, in the send box, the autocomplete and the guild list.",
    ["wn_128_tracker"] = "Fixed - Quest tracker in combat: it no longer jumps from a few quests to all of them. Since 1.2.7 the tracker gets room for every quest, but the game took that room back during fights (shapeshift, pet bar, vehicle...) and TomoMod waited for the end of combat to give it again. It is now given back at once, and \"Max quests displayed\" is also respected during a fight.",
    ["wn_128_questie"] = "New - Questie: TomoMod now runs side by side with it. When Questie's tracker is on, TomoMod leaves the quest tracker alone instead of styling the one Questie hides; when Questie's auto accept or auto turn-in is on, TomoMod's matching automation stands down. A line in chat says so.",
    ["ot_questie_standdown"] = "Questie's quest tracker is on: TomoMod leaves the quest tracker to Questie. To use TomoMod's again, switch Questie's tracker off and type /reload.",
    ["aq_questie_standdown"] = "Questie already accepts or turns in quests: TomoMod's automatic questing stands down for that part, so nothing is done twice.",
    ["mod_spellRanks"] = "New spell ranks",
    ["msg_help_ranks"] = "New spell ranks on the action bars: status, update, reset (update | reset)",
    ["wn_128_ranks"] = "New - Adventure, New ranks: a rank bought at the trainer does not replace the old one on Forever's action bars. Outdated buttons now glow gold, a gold arrow marks the new rank in the spellbook (left click: update the bars, the icon flies to its button; right click: keep the old rank), and a chat line tells you when you leave the trainer. Only the highest rank on your bars is replaced, low ranks kept for mana are left alone. Automatic mode available. /tmf ranks.",
    ["opt_skin_bags_quest_marks"] = "Mark quest items (gold border)",
    ["wn_128_questitems"] = "New - Bags: quest items now wear Blizzard's gold quest border, and so does any item an unfinished objective of your quest log asks for (cloth, meat... even when the game does not flag it), so you do not sell it by mistake. Items that start a quest show the \"!\". The tooltip says which quest wants the item and your progress. Option in the bag settings.",
})

TomoMod_RegisterLocale("frFR", {
    ["wn_128_alts"] = "Corrigé - Courrier, onglet Alts, pour de bon : sur Forever un personnage a un prénom et un nom de famille, et seule la paire est unique. Les personnages étaient enregistrés par leur seul prénom, donc des alts au même prénom s'effaçaient entre eux et la liste restait vide ; le courrier partait aussi au prénom seul. Les personnages sont maintenant enregistrés par leur nom complet (et leur GUID), les lettres partent au nom complet, et seuls les alts de ton ensemble de règles et de ta faction sont listés. Connecte-toi une fois sur chaque personnage pour remplir à nouveau la liste. /tml alts montre ce qui est enregistré.",
    ["wn_128_names"] = "Corrigé - Courrier : un \"Prénom-Nom\" tapé est maintenant lu comme un nom complet, et non comme un nom et un royaume, dans le champ destinataire, l'autocomplétion et la liste de guilde.",
    ["wn_128_tracker"] = "Corrigé - Suivi des quêtes en combat : il ne passe plus de quelques quêtes à toutes. Depuis la 1.2.7 le suivi a de la place pour toutes les quêtes, mais le jeu reprenait cette place pendant les combats (changement de forme, barre du familier, véhicule...) et TomoMod attendait la fin du combat pour la rendre. Elle est maintenant rendue tout de suite, et \"Quêtes affichées max\" est aussi respecté en combat.",
    ["wn_128_questie"] = "Nouveau - Questie : TomoMod cohabite maintenant avec lui. Quand le suivi de Questie est actif, TomoMod laisse le suivi des quêtes tranquille au lieu d'habiller celui que Questie cache ; quand l'acceptation ou le rendu automatique de Questie est actif, l'automatisation correspondante de TomoMod se met en retrait. Une ligne dans le chat le signale.",
    ["ot_questie_standdown"] = "Le suivi des quêtes de Questie est actif : TomoMod lui laisse le suivi des quêtes. Pour retrouver celui de TomoMod, désactive le suivi de Questie puis tape /reload.",
    ["aq_questie_standdown"] = "Questie accepte ou rend déjà les quêtes : l'automatisation des quêtes de TomoMod se met en retrait pour cette partie, rien n'est fait deux fois.",
    ["mod_spellRanks"] = "Nouveaux rangs de sorts",
    ["msg_help_ranks"] = "Nouveaux rangs de sorts sur les barres : état, mise à jour, reset (maj | reset)",
    ["wn_128_ranks"] = "Nouveau - Aventure, Nouveaux rangs : un rang acheté au maître ne remplace pas l'ancien sur les barres de Forever. Les boutons concernés brillent maintenant en doré, une flèche dorée marque le nouveau rang dans le grimoire (clic gauche : mettre à jour les barres, l'icône vole jusqu'à son bouton ; clic droit : garder l'ancien rang), et une ligne dans le chat te prévient en quittant le maître. Seul le rang le plus haut de tes barres est remplacé, les rangs bas gardés pour le mana ne bougent pas. Mode automatique disponible. /tmf rangs.",
    ["opt_skin_bags_quest_marks"] = "Marquer les objets de quête (contour doré)",
    ["wn_128_questitems"] = "Nouveau - Sacs : les objets de quête portent maintenant le contour doré de Blizzard, et tout objet demandé par un objectif en cours de ton journal aussi (tissu, viande... même quand le jeu ne le signale pas), pour ne plus les vendre par erreur. Les objets qui démarrent une quête affichent le \"!\". L'infobulle dit quelle quête veut l'objet et ta progression. Option dans les réglages des sacs.",
})

TomoMod_RegisterLocale("deDE", {
    ["wn_128_alts"] = "Behoben - Post, Reiter Twinks, diesmal wirklich: Auf Forever hat ein Charakter einen Vornamen und einen Nachnamen, und nur das Paar ist eindeutig. Charaktere wurden nur mit dem Vornamen gespeichert, daher löschten sich Twinks mit gleichem Vornamen gegenseitig und die Liste blieb leer; Post ging zudem nur an den Vornamen. Charaktere werden jetzt mit vollem Namen (und GUID) gespeichert, Briefe gehen an den vollen Namen, und nur Twinks deines Regelwerks und deiner Fraktion werden gelistet. Logge dich einmal mit jedem Charakter ein, um die Liste neu zu füllen. /tml alts zeigt, was gespeichert ist.",
    ["wn_128_names"] = "Behoben - Post: Ein getipptes \"Vorname-Nachname\" wird jetzt als ein voller Name gelesen, nicht als Name und Realm, im Empfängerfeld, in der Autovervollständigung und in der Gildenliste.",
    ["wn_128_tracker"] = "Behoben - Questverfolgung im Kampf: Sie springt nicht mehr von wenigen Quests zu allen. Seit 1.2.7 hat die Verfolgung Platz für alle Quests, aber das Spiel nahm diesen Platz im Kampf zurück (Gestaltwandel, Begleiterleiste, Fahrzeug...) und TomoMod gab ihn erst nach dem Kampf wieder. Jetzt sofort, und \"Max. angezeigte Quests\" gilt auch im Kampf.",
    ["wn_128_questie"] = "Neu - Questie: TomoMod läuft jetzt neben Questie. Ist die Verfolgung von Questie aktiv, lässt TomoMod die Questverfolgung in Ruhe, statt die von Questie versteckte zu gestalten; ist die automatische Annahme oder Abgabe von Questie aktiv, hält sich die entsprechende Automatik von TomoMod zurück. Eine Zeile im Chat meldet es.",
    ["ot_questie_standdown"] = "Die Questverfolgung von Questie ist aktiv: TomoMod überlässt Questie die Questverfolgung. Um die von TomoMod zu nutzen, schalte die Verfolgung von Questie aus und tippe /reload.",
    ["aq_questie_standdown"] = "Questie nimmt Quests bereits an oder gibt sie ab: Die Questautomatik von TomoMod hält sich für diesen Teil zurück, nichts passiert doppelt.",
    ["mod_spellRanks"] = "Neue Zauberränge",
    ["msg_help_ranks"] = "Neue Zauberränge auf den Aktionsleisten: Status, Aktualisieren, Zurücksetzen (update | reset)",
    ["wn_128_ranks"] = "Neu - Abenteuer, Neue Ränge: Ein beim Lehrer gekaufter Rang ersetzt auf Forever nicht den alten in den Aktionsleisten. Veraltete Tasten leuchten jetzt golden, ein goldener Pfeil markiert den neuen Rang im Zauberbuch (Linksklick: Leisten aktualisieren, das Symbol fliegt zu seiner Taste; Rechtsklick: alten Rang behalten), und eine Chatzeile meldet sich beim Verlassen des Lehrers. Nur der höchste Rang auf deinen Leisten wird ersetzt, niedrige Ränge zum Manasparen bleiben. Automatikmodus verfügbar. /tmf ranks.",
    ["opt_skin_bags_quest_marks"] = "Questgegenstände markieren (goldener Rahmen)",
    ["wn_128_questitems"] = "Neu - Taschen: Questgegenstände tragen jetzt Blizzards goldenen Questrahmen, ebenso jeder Gegenstand, den ein offenes Ziel deines Questlogs verlangt (Stoff, Fleisch... auch wenn das Spiel ihn nicht markiert), damit du ihn nicht versehentlich verkaufst. Gegenstände, die eine Quest starten, zeigen das \"!\". Der Tooltip nennt die Quest und deinen Fortschritt. Option in den Taschen-Einstellungen.",
})

TomoMod_RegisterLocale("esES", {
    ["wn_128_alts"] = "Corregido - Correo, pestaña Alters, esta vez de verdad: en Forever un personaje tiene nombre y apellido, y solo la pareja es única. Los personajes se guardaban solo por el nombre, así que los alters con el mismo nombre se borraban entre sí y la lista quedaba vacía; el correo también iba solo al nombre. Ahora los personajes se guardan por su nombre completo (y su GUID), las cartas van al nombre completo y solo se listan los alters de tu conjunto de reglas y tu facción. Conéctate una vez con cada personaje para volver a llenar la lista. /tml alts muestra lo guardado.",
    ["wn_128_names"] = "Corregido - Correo: un \"Nombre-Apellido\" escrito ahora se lee como un nombre completo, no como un nombre y un reino, en el destinatario, el autocompletado y la lista de hermandad.",
    ["wn_128_tracker"] = "Corregido - Seguimiento de misiones en combate: ya no salta de unas pocas misiones a todas. Desde la 1.2.7 el seguimiento tiene sitio para todas, pero el juego recuperaba ese sitio durante los combates (cambio de forma, barra de mascota, vehículo...) y TomoMod esperaba al final del combate para devolverlo. Ahora se devuelve al momento, y \"Máx. misiones mostradas\" también se respeta en combate.",
    ["wn_128_questie"] = "Nuevo - Questie: TomoMod ahora convive con él. Si el seguimiento de Questie está activo, TomoMod deja en paz el seguimiento de misiones en lugar de decorar el que Questie oculta; si la aceptación o entrega automática de Questie está activa, la automatización equivalente de TomoMod se retira. Una línea en el chat lo indica.",
    ["ot_questie_standdown"] = "El seguimiento de misiones de Questie está activo: TomoMod le deja el seguimiento de misiones. Para volver al de TomoMod, desactiva el seguimiento de Questie y escribe /reload.",
    ["aq_questie_standdown"] = "Questie ya acepta o entrega misiones: la automatización de misiones de TomoMod se retira para esa parte, nada se hace dos veces.",
    ["mod_spellRanks"] = "Nuevos rangos de hechizos",
    ["msg_help_ranks"] = "Nuevos rangos de hechizos en las barras: estado, actualizar, reiniciar (update | reset)",
    ["wn_128_ranks"] = "Nuevo - Aventura, Nuevos rangos: en Forever un rango comprado al instructor no reemplaza al antiguo en las barras. Los botones desfasados brillan ahora en dorado, una flecha dorada marca el nuevo rango en el libro de hechizos (clic izquierdo: actualizar las barras, el icono vuela hasta su botón; clic derecho: mantener el rango antiguo) y una línea en el chat avisa al dejar al instructor. Solo se reemplaza el rango más alto de tus barras; los rangos bajos guardados para ahorrar maná no se tocan. Modo automático disponible. /tmf ranks.",
    ["opt_skin_bags_quest_marks"] = "Marcar objetos de misión (borde dorado)",
    ["wn_128_questitems"] = "Nuevo - Bolsas: los objetos de misión llevan ahora el borde dorado de Blizzard, y también cualquier objeto que pida un objetivo pendiente de tu registro (tela, carne... aunque el juego no lo marque), para no venderlo por error. Los objetos que inician una misión muestran el \"!\". La descripción indica qué misión lo quiere y tu progreso. Opción en los ajustes de las bolsas.",
})

TomoMod_RegisterLocale("itIT", {
    ["wn_128_alts"] = "Corretto - Posta, scheda Alt, stavolta davvero: su Forever un personaggio ha nome e cognome, e solo la coppia è unica. I personaggi venivano salvati col solo nome, quindi gli alt con lo stesso nome si cancellavano a vicenda e la lista restava vuota; la posta partiva anche al solo nome. Ora i personaggi sono salvati col nome completo (e il GUID), le lettere vanno al nome completo e sono elencati solo gli alt del tuo set di regole e della tua fazione. Entra una volta con ciascun personaggio per riempire di nuovo la lista. /tml alts mostra cosa è salvato.",
    ["wn_128_names"] = "Corretto - Posta: un \"Nome-Cognome\" digitato ora è letto come un nome completo, non come un nome e un reame, nel destinatario, nel completamento automatico e nella lista di gilda.",
    ["wn_128_tracker"] = "Corretto - Tracciamento missioni in combattimento: non salta più da poche missioni a tutte. Dalla 1.2.7 il tracciamento ha spazio per tutte, ma il gioco se lo riprendeva durante i combattimenti (cambio di forma, barra del famiglio, veicolo...) e TomoMod aspettava la fine del combattimento per restituirlo. Ora viene restituito subito, e il massimo di missioni mostrate vale anche in combattimento.",
    ["wn_128_questie"] = "Nuovo - Questie: TomoMod ora convive con Questie. Se il tracciamento di Questie è attivo, TomoMod lascia stare il tracciamento missioni invece di decorare quello che Questie nasconde; se l'accettazione o la consegna automatica di Questie è attiva, l'automazione corrispondente di TomoMod si fa da parte. Una riga in chat lo segnala.",
    ["ot_questie_standdown"] = "Il tracciamento missioni di Questie è attivo: TomoMod lascia a Questie il tracciamento missioni. Per riavere quello di TomoMod, disattiva il tracciamento di Questie e digita /reload.",
    ["aq_questie_standdown"] = "Questie accetta o consegna già le missioni: l'automazione missioni di TomoMod si fa da parte per quella funzione, niente viene fatto due volte.",
    ["mod_spellRanks"] = "Nuovi gradi degli incantesimi",
    ["msg_help_ranks"] = "Nuovi gradi degli incantesimi sulle barre: stato, aggiornamento, azzeramento (update | reset)",
    ["wn_128_ranks"] = "Nuovo - Avventura, Nuovi gradi: su Forever un grado comprato dall'istruttore non sostituisce il vecchio sulle barre. I pulsanti superati ora brillano d'oro, una freccia dorata segna il nuovo grado nel libro degli incantesimi (clic sinistro: aggiorna le barre, l'icona vola fino al suo pulsante; clic destro: tieni il vecchio grado) e una riga in chat avvisa quando lasci l'istruttore. Viene sostituito solo il grado più alto sulle barre; i gradi bassi tenuti per il mana restano. Modalità automatica disponibile. /tmf ranks.",
    ["opt_skin_bags_quest_marks"] = "Segna gli oggetti delle missioni (bordo dorato)",
    ["wn_128_questitems"] = "Nuovo - Borse: gli oggetti delle missioni ora hanno il bordo dorato di Blizzard, e anche ogni oggetto richiesto da un obiettivo in corso del registro (stoffa, carne... anche se il gioco non lo segnala), così non lo vendi per sbaglio. Gli oggetti che avviano una missione mostrano il \"!\". Il tooltip dice quale missione lo vuole e il tuo progresso. Opzione nelle impostazioni delle borse.",
})

TomoMod_RegisterLocale("ptBR", {
    ["wn_128_alts"] = "Corrigido - Correio, aba Alts, agora de verdade: no Forever um personagem tem nome e sobrenome, e só o par é único. Os personagens eram salvos só pelo nome, então alts com o mesmo nome se apagavam e a lista ficava vazia; o correio também ia só para o nome. Agora os personagens são salvos pelo nome completo (e GUID), as cartas vão para o nome completo e só aparecem alts do seu conjunto de regras e da sua facção. Entre uma vez com cada personagem para preencher a lista de novo. /tml alts mostra o que está salvo.",
    ["wn_128_names"] = "Corrigido - Correio: um \"Nome-Sobrenome\" digitado agora é lido como um nome completo, não como nome e reino, no destinatário, no preenchimento automático e na lista da guilda.",
    ["wn_128_tracker"] = "Corrigido - Rastreador de missões em combate: não pula mais de poucas missões para todas. Desde a 1.2.7 o rastreador tem espaço para todas, mas o jogo tomava esse espaço de volta nas lutas (mudança de forma, barra do mascote, veículo...) e o TomoMod esperava o fim do combate para devolvê-lo. Agora é devolvido na hora, e o \"Máx. de missões exibidas\" também vale em combate.",
    ["wn_128_questie"] = "Novo - Questie: o TomoMod agora convive com ele. Com o rastreador do Questie ativo, o TomoMod deixa o rastreador de missões em paz em vez de estilizar o que o Questie esconde; com o aceite ou a entrega automática do Questie ativos, a automação equivalente do TomoMod se retira. Uma linha no chat avisa.",
    ["ot_questie_standdown"] = "O rastreador de missões do Questie está ativo: o TomoMod deixa o rastreador de missões com o Questie. Para voltar ao do TomoMod, desative o rastreador do Questie e digite /reload.",
    ["aq_questie_standdown"] = "O Questie já aceita ou entrega missões: a automação de missões do TomoMod se retira dessa parte, nada é feito duas vezes.",
    ["mod_spellRanks"] = "Novas patentes de feitiços",
    ["msg_help_ranks"] = "Novas patentes de feitiços nas barras: estado, atualizar, redefinir (update | reset)",
    ["wn_128_ranks"] = "Novo - Aventura, Novas patentes: no Forever uma patente comprada no instrutor não substitui a antiga nas barras. Os botões desatualizados agora brilham em dourado, uma seta dourada marca a nova patente no grimório (clique esquerdo: atualizar as barras, o ícone voa até o botão; clique direito: manter a patente antiga) e uma linha no chat avisa ao sair do instrutor. Só a patente mais alta das barras é trocada; patentes baixas guardadas para economizar mana ficam. Modo automático disponível. /tmf ranks.",
    ["opt_skin_bags_quest_marks"] = "Marcar itens de missão (borda dourada)",
    ["wn_128_questitems"] = "Novo - Bolsas: itens de missão agora têm a borda dourada da Blizzard, assim como qualquer item que um objetivo em andamento do registro pede (tecido, carne... mesmo quando o jogo não marca), para não vendê-lo por engano. Itens que iniciam uma missão mostram o \"!\". A dica diz qual missão quer o item e o seu progresso. Opção nas configurações das bolsas.",
})
